 public ContentEditorForm(string filename){sourceFile=filename;document=new ContentDocument(File.ReadAllText(filename));Text="Scenario Converter — Edit content · "+Path.GetFileName(filename);Size=new Size(1250,850);MinimumSize=new Size(950,650);StartPosition=FormStartPosition.CenterParent;Font=new Font("Segoe UI",10);Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);
