  FillGrid();
 }
 void MarkPending(){if(!loading){pending=true;status.Text="Edit belum diterapkan. Klik Terapkan atau Simpan sebagai.";}}
 void Filter(){if(!ResolvePending())return;FillGrid();}
 void FillGrid(){loading=true;grid.Rows.Clear();string key=new[]{"all","id","chapter","subChapter","namaContent"}[searchBy.SelectedIndex];foreach(int index in document.Search(key,search.Text)){var item=document.Item(index);int row=grid.Rows.Add(Value(item,"id"),Value(item,"chapter"),Value(item,"subChapter"),Value(item,"namaContent"));grid.Rows[row].Tag=index;}loading=false;selected=-1;if(grid.Rows.Count>0){grid.Rows[0].Selected=true;Choose();}else{loading=true;foreach(var box in fields.Values){box.Clear();box.Enabled=false;}scenario.Clear();scenario.Enabled=false;loading=false;status.Text="Tidak ada content yang cocok.";}}
 static string Value(Dictionary<string,object> item,string key){object value;item.TryGetValue(key,out value);return Convert.ToString(value);}
 void Choose(){if(loading||grid.SelectedRows.Count==0)return;int next=(int)grid.SelectedRows[0].Tag;if(next==selected)return;int previous=selected;if(!ResolvePending()){loading=true;foreach(DataGridViewRow row in grid.Rows)row.Selected=(int)row.Tag==previous;loading=false;return;}selected=next;LoadSelected();}
 void LoadSelected(){pendingImport.Clear();loading=true;var item=document.Item(selected);foreach(var pair in fields){pair.Value.Text=Value(item,pair.Key);pair.Value.Enabled=item.ContainsKey(pair.Key);}scenario.Enabled=true;scenario.Text=document.FieldRaw(selected,"scenario");pending=false;loading=false;status.Text="ID content "+Value(item,"id")+" · "+document.Count+" content. Hanya field yang diedit akan diterapkan.";}
 bool ResolvePending(){if(!pending)return true;var answer=MessageBox.Show(this,"Terapkan edit content saat ini sebelum melanjutkan?","Edit belum diterapkan",MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);if(answer==DialogResult.Cancel)return false;if(answer==DialogResult.No){pendingImport.Clear();pending=false;return true;}return ApplySafe();}
 bool ApplySafe(){try{ApplySelected();return true;}catch(Exception ex){MessageBox.Show(this,ex.Message,"Content tidak dapat diperbarui",MessageBoxButtons.OK,MessageBoxIcon.Error);return false;}}
 void ApplySelected(){if(selected<0)throw new Exception("Pilih content terlebih dahulu.");var item=document.Item(selected);var edits=new Dictionary<string,string>(pendingImport);foreach(var pair in fields)if(pair.Value.Enabled&&pair.Value.Text!=Value(item,pair.Key))edits.Add(pair.Key,ContentDocument.Encode(pair.Value.Text));if(scenario.Text!=document.FieldRaw(selected,"scenario")){ValidateScenario(scenario.Text);edits.Add("scenario",scenario.Text);}if(edits.Count>0){document.Patch(selected,edits);dirty=true;}pendingImport.Clear();pending=false;loading=true;foreach(DataGridViewRow row in grid.Rows)if((int)row.Tag==selected){var updated=document.Item(selected);row.SetValues(Value(updated,"id"),Value(updated,"chapter"),Value(updated,"subChapter"),Value(updated,"namaContent"));}loading=false;status.Text="Perubahan diterapkan ke content ID "+Value(item,"id")+". Content lain dipertahankan. Klik Simpan sebagai untuk menulis file.";}
 static void ValidateScenario(string text){var array=Json.DeserializeObject(text) as object[];if(array==null)throw new Exception("scenario harus berupa array JSON [].");var ids=new HashSet<string>();foreach(var value in array){var node=value as Dictionary<string,object>;if(node==null||!node.ContainsKey("id"))throw new Exception("Setiap langkah harus berupa object dengan id.");string id=Convert.ToString(node["id"]);if(!ids.Add(id))throw new Exception("ID langkah duplikat: "+id);foreach(string key in new[]{"prev_id","next_id"})if(!node.ContainsKey(key)||!(node[key] is object[]))throw new Exception(key+" langkah "+id+" harus array.");object parameter;if(node.TryGetValue("parameterscript",out parameter)&&parameter!=null){if(!(parameter is string))throw new Exception("parameterscript langkah "+id+" harus string JSON atau null.");if((string)parameter!="")Json.DeserializeObject((string)parameter);}}}
 bool SaveDocument(){try{if(pending&&!ApplySafe())return false;using(var dialog=new SaveFileDialog {Filter="JSON|*.json",DefaultExt="json",AddExtension=true,FileName=Path.GetFileNameWithoutExtension(sourceFile)+"-edited.json"}){if(dialog.ShowDialog()!=DialogResult.OK)return false;File.WriteAllText(dialog.FileName,document.Export(standard.Checked),new UTF8Encoding(false));dirty=false;status.Text="Tersimpan: "+dialog.FileName;return true;}}catch(Exception ex){MessageBox.Show(this,ex.Message,"Gagal menyimpan",MessageBoxButtons.OK,MessageBoxIcon.Error);return false;}}
